import { useTranslation } from 'react-i18next';
import { useData } from 'vike-react/useData';
import { Fragment, useMemo, useState } from 'react';
import type { ColumnDef, SortingState } from '@tanstack/react-table';
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  flexRender,
  getFilteredRowModel
} from '@tanstack/react-table';

import { Text } from '../../components/ui/text';
import type { PageData } from './+data';
import { Metadata } from '~/components/layout/Metadata';
import { getAlbumArtPublicPath } from '~/utils/assets';
import { Stack, styled } from 'styled-system/jsx';
import { Table } from '~/components/ui/table';
import { Link } from '~/components/ui/link';
import { Input } from '~/components/ui/input';

export function Page() {
  // eslint-disable-next-line react-compiler/react-compiler
  'use no memo';

  const { t } = useTranslation();

  const data: PageData = useData();
  const title = t('title');

  const [globalFilter, setGlobalFilter] = useState('');
  const [sorting, setSorting] = useState<SortingState>([]);

  type Song = PageData['songs'][0];
  type DifficultyKey = keyof Song['difficulty'];

  const difficultyConfigs: {
    key: DifficultyKey;
    param: '1' | '2' | '3' | '4';
    label: string;
  }[] = [
    { key: 'normal', param: '1', label: t('song_table.normal') },
    { key: 'hard', param: '2', label: t('song_table.hard') },
    { key: 'expert', param: '3', label: t('song_table.expert') },
    { key: 'master', param: '4', label: t('song_table.master') }
  ];

  const columns = useMemo<ColumnDef<Song>[]>(
    () => [
      {
        accessorKey: 'id',
        header: ({ column }) => (
          <Table.Header
            onClick={column.getCanSort() ? column.getToggleSortingHandler() : undefined}
            hideBelow="md"
          >
            {/* Album Art Column */}
          </Table.Header>
        ),
        cell: (info) => (
          <Table.Cell hideBelow="md" width="16" px="0">
            <Link href={`/${info.row.original.id}`}>
              <styled.img
                src={getAlbumArtPublicPath(info.row.original.id)}
                alt={`${info.row.original.title} album art`}
                objectFit="contain"
              />
            </Link>
          </Table.Cell>
        ),
        enableSorting: false
      },
      {
        accessorKey: 'title',
        header: ({ column }) => (
          <Table.Header
            onClick={column.getCanSort() ? column.getToggleSortingHandler() : undefined}
          >
            {t('song_table.name')}
            {column.getIsSorted() === 'asc' ? ' ▲' : column.getIsSorted() === 'desc' ? ' ▼' : null}
          </Table.Header>
        ),
        cell: (info) => (
          <Table.Cell>
            <Link href={`/${info.row.original.id}`} fontWeight="bold">
              {info.getValue() as string}
            </Link>
          </Table.Cell>
        ),
        sortingFn: 'alphanumeric'
      },
      {
        accessorKey: 'description',
        header: ({ column }) => (
          <Table.Header
            onClick={column.getCanSort() ? column.getToggleSortingHandler() : undefined}
            hideBelow="md"
          >
            {t('song_table.description')}
            {column.getIsSorted() === 'asc' ? ' ▲' : column.getIsSorted() === 'desc' ? ' ▼' : null}
          </Table.Header>
        ),
        cell: (info) => <Table.Cell hideBelow="md">{info.getValue() as string}</Table.Cell>,
        sortingFn: 'alphanumeric'
      },
      {
        accessorKey: 'duration',
        header: ({ column }) => (
          <Table.Header
            onClick={column.getCanSort() ? column.getToggleSortingHandler() : undefined}
            hideBelow="md"
            textAlign="center"
          >
            {t('song_table.length')}
            {{
              asc: ' ▲',
              desc: ' ▼'
            }[column.getIsSorted() as string] ?? null}
          </Table.Header>
        ),
        cell: (info) => {
          const totalSeconds = Math.floor((info.getValue() as number) / 1000);
          const minutes = Math.floor(totalSeconds / 60);
          const seconds = totalSeconds % 60;
          const formattedSeconds = seconds < 10 ? `0${seconds}` : seconds;
          return (
            <Table.Cell hideBelow="md" textAlign="center">
              {`${minutes}:${formattedSeconds}`}
            </Table.Cell>
          );
        },
        sortingFn: 'datetime'
      },
      ...difficultyConfigs.map(
        (config): ColumnDef<Song> => ({
          accessorFn: (row) => row.difficulty[config.key],
          id: config.key,
          header: ({ column }) => (
            <Table.Header
              onClick={column.getCanSort() ? column.getToggleSortingHandler() : undefined}
              minW="16"
              p={{ base: 1, md: 4 }}
              textAlign="center"
            >
              {config.label}
              {column.getIsSorted() === 'asc'
                ? ' ▲'
                : column.getIsSorted() === 'desc'
                  ? ' ▼'
                  : null}
            </Table.Header>
          ),
          sortingFn: 'alphanumeric',
          cell: (info) => (
            <Table.Cell
              minW="16"
              p={{ base: 0, md: 4 }}
              textAlign="center"
              bgColor={`difficulty.${config.key}.bg`}
            >
              <Link href={`/${info.row.original.id}?difficulty=${config.param}`}>
                <Stack gap="0" alignItems="center" textAlign="center">
                  <Stack gap="0.5" direction="row" alignItems="baseline">
                    <Text color="fg.default" fontSize="xs">
                      Lv.
                    </Text>
                    <Text fontSize="xl" fontWeight="bold" lineHeight="1">
                      {info.getValue() as number}
                    </Text>
                  </Stack>
                  <Text hideBelow="md" color="fg.default" fontSize="xs" lineHeight="1">
                    ({info.row.original.maxCombo[config.key]})
                  </Text>
                </Stack>
              </Link>
            </Table.Cell>
          )
        })
      )
    ],
    [t, difficultyConfigs]
  );

  const table = useReactTable({
    data: data.songs,
    columns,
    state: {
      sorting,
      globalFilter
    },
    onSortingChange: setSorting,
    onGlobalFilterChange: setGlobalFilter,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel()
  });

  return (
    <>
      <Metadata title={title} />
      <Stack alignItems="center" w="full" _print={{ display: 'none' }}>
        <Text textAlign="center" fontSize="3xl" fontWeight="bold">
          {title}
        </Text>
        <Text textAlign="center">{t('description')}</Text>

        <Input
          placeholder="Search songs..."
          value={globalFilter ?? ''}
          onChange={(e) => setGlobalFilter(e.target.value)}
          mb={4} // Margin bottom for spacing
        />

        <Table.Root>
          <Table.Head>
            {table.getHeaderGroups().map((headerGroup) => (
              <Table.Row key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <Fragment key={header.id}>
                    {flexRender(header.column.columnDef.header, header.getContext())}
                  </Fragment>
                ))}
              </Table.Row>
            ))}
          </Table.Head>
          <Table.Body>
            {table.getRowModel().rows.map((row) => (
              <Table.Row key={row.id}>
                {row
                  .getVisibleCells()
                  .map((cell) => flexRender(cell.column.columnDef.cell, cell.getContext()))}
              </Table.Row>
            ))}
          </Table.Body>
        </Table.Root>
      </Stack>
    </>
  );
}
